Array getExtendedMemcacheStats(const String& type, int slabid, int limit) {
    Array stats;
    MemcacheData* data = Memcache::get_data();
    if (!data || !data->connect()) {
        return Array();
    }

    for (int i = 0; i < data->server_count; ++i) {
        MemcacheServer* server = data->servers[i];
        std::string key = server->hostname + ":" + std::to_string(server->port);
        MemcacheStat* serverStats = server->get_stats(type, slabid, limit);

        if (serverStats) {
            stats.set(String(key.c_str()), serverStats);
        }
    }

    data->free_stats();
    return stats;
}

